  if(unknown.length)throw new Error(`Unclassified persistent state fields: ${unknown.join(',')}`);
  const previous={};for(const key of [...groups.map(group=>STORAGE_KEYS[group]),STORAGE_KEYS.commit,STORAGE_KEYS.migration])previous[key]=localStorage.getItem(key);
