    for(const group of groups)localStorage.setItem(STORAGE_KEYS[group],JSON.stringify(storagePayload(group,value,revision)));
    const commitRaw=JSON.stringify({schema:STORAGE_SCHEMA_VERSION,revision,groups});localStorage.setItem(STORAGE_KEYS.commit,commitRaw);
    if(migration)localStorage.setItem(STORAGE_KEYS.migration,JSON.stringify({schema:STORAGE_SCHEMA_VERSION,from:LEGACY_STORAGE_KEY,to:'purpose-separated-v1',revision}));
