  for(const group of Object.keys(STORAGE_GROUP_FIELDS))for(const key of STORAGE_GROUP_FIELDS[group])classified[key]=Object.prototype.hasOwnProperty.call(legacy,key)?legacy[key]:base[key];
  const migrated=storedStateFromParsed(classified);writeNamespacedState(migrated,{migration:true});localStorage.removeItem(LEGACY_STORAGE_KEY);return migrated
}

