function persist(reason='change'){
  try{
    if(!storageWriteIsCurrent()){warnConcurrentStorageChange();return false}
    if(state.currentSession)state.currentSession.lastSavedAt=new Date().toISOString();
    writeStateToStorage();storageOK=true;announce(`Saved on this device: ${reason}.`);return true
  }catch(e){
    /* Quota fallback: preserve older feedback; drop only the newest embedded screenshot, then retry once. */
    try{
      const reports=Array.isArray(state.websiteReports)?state.websiteReports:[];
      let idx=-1;for(let i=reports.length-1;i>=0;i--){if(reports[i]?.screenshotDataUrl){idx=i;break}}
      if(idx>=0){
        const previous={screenshotDataUrl:reports[idx].screenshotDataUrl,screenshotStored:reports[idx].screenshotStored};
        reports[idx]={...reports[idx],screenshotDataUrl:null,screenshotStored:false};
        try{writeStateToStorage();storageOK=true;showStorageNotice('The newest feedback screenshot could not be stored, but your feedback text and earlier saved screenshots were preserved.');announce('Feedback saved without the newest embedded screenshot.');return true}
        catch(_){reports[idx]={...reports[idx],...previous}}
