function deriveObjectiveState(events){
  const sorted=[...events].sort((a,b)=>Date.parse(a.answeredAt)-Date.parse(b.answeredAt));
  const practised=sorted.length>0;
  const correct=sorted.filter(eligibleCorrect);
  let stateName=practised?'practised':'unseen';
  if(correct.length)stateName='first_correct';
  let remembered=null,repeated=null;
  for(let i=1;i<correct.length;i++){
    const prev=correct[i-1],cur=correct[i];
    const gap=Date.parse(cur.answeredAt)-Date.parse(prev.answeredAt);
    if(cur.sessionId!==prev.sessionId && gap>=DAY){remembered=cur;stateName='remembered_later';break}
  }
  if(remembered){
    const idx=correct.indexOf(remembered);
    for(let i=idx+1;i<correct.length;i++){
      const cur=correct[i];
      if(cur.sessionId!==remembered.sessionId && Date.parse(cur.answeredAt)-Date.parse(remembered.answeredAt)>=DAY && cur.questionId!==remembered.questionId){repeated=cur;stateName='repeated_later';break}
    }
  }
  const latest=sorted.at(-1)||null,latestMiss=[...sorted].reverse().find(e=>e.correct===false)||null,lastCorrect=correct.at(-1)||null;
  const misconceptionPriority=Boolean(latest&&latest.correct===false&&latest.confidence===2);
  const fragileCorrect=Boolean(latest&&latest.correct===true&&(latest.confidence===0||latest.confidence===null));
  const reviewDue=Boolean(latest&&(latest.correct===false||fragileCorrect));
  const successfulSessions=new Set(correct.map(e=>e.sessionId).filter(Boolean)).size;
  const feedbackViewedAfterMiss=Boolean(latestMiss?.feedbackViewedAt);
  const lastSuccessfulRetrievalAt=lastCorrect?.answeredAt||null;
  let nextDueBucket='new';
  if(latest){
    if(misconceptionPriority)nextDueBucket='next-session-priority';
    else if(latest.correct===false)nextDueBucket='next-session';
    else if(fragileCorrect)nextDueBucket='soon';
    else if(!remembered)nextDueBucket=Date.now()-Date.parse(lastCorrect?.answeredAt||0)>=DAY?'due-now':'after-gap';
    else nextDueBucket='later';
  }
  return {state:stateName,practised,firstCorrect:correct[0]||null,rememberedLater:remembered,repeatedLater:repeated,reviewDue,misconceptionPriority,fragileCorrect,successfulSessions,feedbackViewedAfterMiss,lastSuccessfulRetrievalAt,nextDueBucket,sourceNeedsRecheck:false,lastAttempt:latest};
}

function deriveCourseProjection(courseId){
  const course=COURSES[courseId];if(!course)return null;
  const objectives={};const topics={};
  course.topics.forEach(t=>{
    let practised=0,remembered=0,review=0;
    t.objectives.forEach(o=>{const d=deriveObjectiveState(objectiveEvents(courseId,o));objectives[o]=d;if(d.practised)practised++;if(d.rememberedLater)remembered++;if(d.reviewDue)review++});
    topics[t.id]={practised,remembered,review,total:t.objectives.length};
  });
  return {courseId,objectives,topics};
}

function priorityScore(question){
  const ev=objectiveEvents(question.courseId,question.objectiveId),d=deriveObjectiveState(ev),last=d.lastAttempt;if(!last)return 30;
  if(d.misconceptionPriority)return 100;
  if(last.correct===false)return 80;
  if(d.fragileCorrect)return 60;
  if(d.reviewDue)return 70;
  if(d.firstCorrect&&!d.rememberedLater)return d.nextDueBucket==='due-now'?55:25;
  if(d.rememberedLater)return 15;
  return 20;
}

function topicReason(courseId,topicId){
  const p=deriveCourseProjection(courseId).topics[topicId];if(!p)return '';
  if(p.review>0)return p.review===1?'1 idea to review again.':`${p.review} ideas to review again.`;
  if(p.remembered>0)return p.remembered===1?'You remembered 1 idea again later.':`You remembered ${p.remembered} ideas again later.`;
  if(p.practised>0)return `You've practised ${p.practised} of ${p.total} idea${p.total===1?'':'s'}.`;
  return "You haven't studied this yet."
}

function projectionDelta(before,after){
  const changed=[];
  Object.keys(after.objectives).forEach(id=>{
    const b=before.objectives[id]?.state||'unseen',a=after.objectives[id]?.state||'unseen';
    const rank={unseen:0,practised:1,first_correct:2,remembered_later:3,repeated_later:4};
    if(rank[a]>rank[b] && rank[a]>=3)changed.push({objectiveId:id,from:b,to:a});
  });return changed;
}

