  if(points.length<3)return {points,closed:false};const first=points[0],last=points.at(-1),gap=Math.hypot(last.x-first.x,last.y-first.y),pathLength=lassoPathLength(points),closeThreshold=Math.max(18,Math.min(56,pathLength*.14));if(gap>closeThreshold)return {points,closed:false};if(gap<3)return {points:[...points,{...first}],closed:true};
