function sgAnimate(el,frames,opts){
  if(!el||typeof el.animate!=='function')return Promise.resolve(null);
  let anim;try{anim=el.animate(frames,Object.assign({fill:'both'},opts))}catch(_){return Promise.resolve(null)}
  const guard=new Promise(res=>setTimeout(res,(opts.duration||0)+160));
  return Promise.race([anim.finished.catch(()=>null),guard]).then(()=>anim)
}

function sgCreateStepController(opts){
  const {count,host,container,regions,render,onCommitted}=opts;
  let index=opts.initial||0,busy=false,queued=null;
  const alive=()=>host.isConnected;
  async function go(to,{source=null,relative=false}={}){
    to=Math.max(0,Math.min(count-1,Number(to)));
    if(!Number.isFinite(to)||!alive())return false;
    if(busy){if(!relative)queued={to,source};return false}
    if(to===index)return false;
    busy=true;host.setAttribute('data-sg-swapping','');
    const dir=to>index?1:-1,motion=sgMotionOn(),from=index;
    const regionEls=regions();
    regionEls.forEach(r=>r&&r.setAttribute('inert',''));
    const startH=container?container.getBoundingClientRect().height:0;
    let outs=[];
    if(motion){
      outs=await sgAnimateGroup(sgSwapTargets(regionEls),[{opacity:1,transform:'none'},{opacity:0,transform:`translateX(${-dir*SG_MOTION.shift}px)`}],{duration:SG_MOTION.outMs,easing:SG_MOTION.easeIn});
      if(!alive()){outs.forEach(a=>a?.cancel?.());busy=false;return false}
    }
    index=to;
    render(index,{from,dir});
    const fresh=regions();
    fresh.forEach(r=>r&&r.removeAttribute('inert'));
    let heightAnim=null;
    if(motion&&container){
      const endH=container.getBoundingClientRect().height;
      if(Math.abs(endH-startH)>2){const prevOverflow=container.style.overflow;container.style.overflow='hidden';heightAnim=sgAnimate(container,[{height:startH+'px'},{height:endH+'px'}],{duration:SG_MOTION.heightMs,easing:SG_MOTION.easeOut}).then(a=>{a?.cancel?.();container.style.overflow=prevOverflow})}
    }
    const inTargets=sgSwapTargets(fresh);
    if(motion){
      // In-animations are created synchronously here, so cancelling the out-animation fills in
      // the same task never paints an un-faded frame.
      const inP=sgAnimateGroup(inTargets,[{opacity:0,transform:`translateX(${dir*SG_MOTION.shift}px)`},{opacity:1,transform:'none'}],{duration:SG_MOTION.inMs,easing:SG_MOTION.easeOut});
      outs.forEach(a=>a?.cancel?.());
      await Promise.all([inP.then(list=>list.forEach(a=>a?.cancel?.())),heightAnim]);
    }
    host.removeAttribute('data-sg-swapping');busy=false;
    if(!alive())return false;
    onCommitted?.(index,{from,dir,source});
    if(queued){const q=queued;queued=null;if(q.to!==index)return go(q.to,{source:q.source})}
    return true
  }
  return{go,next:source=>go(index+1,{source,relative:true}),back:source=>go(index-1,{source,relative:true}),get index(){return index},get busy(){return busy}}
}

