function sgTourSettleFocus({source,heading,headingEl,announceText}){
  const active=document.activeElement;
  const keep=SG_TOUR_FOCUS_POLICY!=='heading'&&source&&source.isConnected&&!source.disabled&&(active===source);
  if(keep){announce(announceText);return}
  const h=headingEl||document.getElementById(heading);
  if(h){if(!h.hasAttribute('tabindex'))h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}
}

function sgTourRevealIfNeeded(card,headingEl){
  if(!card||!headingEl)return;
  const top=headingEl.getBoundingClientRect().top;
  if(top>=0&&top<innerHeight-40)return;
  const y=window.scrollY+card.getBoundingClientRect().top-12;
  if(sgMotionOn())window.scrollTo({top:Math.max(0,y),behavior:'smooth'});else sgInstantScrollTo(y);
}

function sgMountStepTour(cfg){
