  const host=root.querySelector('.tour-page'),card=host.querySelector('.tour-card'),body=host.querySelector('.tour-step-body'),visual=host.querySelector('.tour-visual'),meta=host.querySelector('.tour-step-meta'),back=document.getElementById(cfg.backId),next=document.getElementById(cfg.nextId),dotEls=[...host.querySelectorAll(`[${cfg.dotAttr}]`)];
  const paintStep=i=>{const step=cfg.steps[i];body.innerHTML=cfg.bodyMarkup(step,i);visual.dataset.kind=step.kind;visual.innerHTML=cfg.visualMarkup(step,i);
    dotEls.forEach((d,k)=>{d.classList.toggle('active',k===i);d.setAttribute('aria-current',k===i?'step':'false')});
    meta.textContent=`${i+1} / ${n}`;back.disabled=i===0;next.textContent=i===n-1?cfg.finalLabel:'Next';cfg.bind?.(step,i)};
  const ctl=sgCreateStepController({count:n,host,container:card,regions:()=>[body,visual],render:i=>paintStep(i),onCommitted:(i,{source})=>{const step=cfg.steps[i];cfg.onStepView?.(step,i);const h=document.getElementById(cfg.headingId);sgTourSettleFocus({source,headingEl:h,announceText:`Step ${i+1} of ${n}. ${step.title}`});sgTourRevealIfNeeded(card,h)}});
