  back.addEventListener('click',()=>ctl.back(back));
  next.addEventListener('click',()=>{if(ctl.busy)return;if(ctl.index>=n-1){if(finishing)return;finishing=true;cfg.onComplete();return}ctl.next(next)});
  cfg.afterMount?.(host,ctl);
  return ctl
}

