function nextClassNoteTarget(courseId){
  const notes=classNotesFor(courseId);if(!notes.length)return null;
  const firstOpenSection=note=>{const done=noteDoneIds(note.id),idx=note.sections.findIndex(sec=>!done.includes(sec.id));return idx>=0?{note,section:note.sections[idx],sectionIndex:idx}:null};
  const currentIndex=notes.findIndex(n=>n.id===state.lastClassNoteId);
  if(currentIndex>=0){
    const current=firstOpenSection(notes[currentIndex]);if(current)return current;
    for(let offset=1;offset<=notes.length;offset++){const candidate=notes[(currentIndex+offset)%notes.length];if(!classNoteProgress(candidate).complete){const target=firstOpenSection(candidate);if(target)return target}}
    return null;
  }
  for(const note of notes){if(!classNoteProgress(note).complete){const target=firstOpenSection(note);if(target)return target}}
  return null;
}

