function studyCalendarMarkup(c){
  const notes=classNotesFor(c.id),assessments=CLASS_ASSESSMENTS[c.id]||[];if(!notes.length&&!assessments.length)return '';
  const year=(assessments[0]?.date?new Date(assessments[0].date):new Date()).getFullYear(),events=[];
  notes.forEach(n=>{const d=parseClassDateLabel(n.date,year);if(d)events.push({date:d,kind:'note',id:n.id,title:n.title,label:'Class notes'})});
  assessments.forEach(a=>events.push({date:new Date(a.date),kind:'quiz',id:a.id,title:a.title,label:'Assessment'}));events.sort((a,b)=>a.date-b.date);
  const fmtDay=d=>new Intl.DateTimeFormat('en-CA',{weekday:'short'}).format(d),fmtDate=d=>new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric'}).format(d);
  const rows=events.map(e=>`<button class="calendar-day has-event week-event ${e.kind==='quiz'?'quiz-day':''}" type="button" data-calendar-kind="${e.kind}" data-calendar-id="${esc(e.id)}" data-calendar-search="${esc((fmtDay(e.date)+' '+fmtDate(e.date)+' '+e.title+' '+e.label).toLowerCase())}" aria-label="${esc(fmtDay(e.date)+' '+fmtDate(e.date)+': '+e.title)}"><span class="week-day"><b>${esc(fmtDay(e.date))}</b><small>${esc(fmtDate(e.date))}</small></span><span class="event-dot"></span><span class="week-event-copy"><strong>${esc(e.title)}</strong><small>${esc(e.label)}</small></span></button>`).join('');
  return `<details class="study-calendar" open><summary><span>Class schedule</span><span class="tiny">${events.length} upcoming class item${events.length===1?'':'s'}</span></summary><div class="study-calendar-body"><div class="calendar-month-head"><div><div class="eyebrow">This class</div><strong>${esc(c.name)}</strong></div><a class="btn small" href="#/courses">Find / switch class</a></div><label class="week-filter-label" for="classScheduleFilter">Filter this schedule<input id="classScheduleFilter" type="search" placeholder="Notes, quiz, day…" autocomplete="off"></label><div class="calendar-grid weekly-schedule">${rows}</div><div class="tiny weekly-schedule-note">School days and assessments stay in one short timeline. Tap an item to open it.</div></div></details>`
