  function spawn(now=performance.now()){const q=qs[qIndex++%qs.length],decoys=shuffledIndexes(q.choices.length).filter(i=>i!==q.answer).slice(0,2),choices=[q.answer,...decoys];for(let i=choices.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]]}tokens=choices.map((choice,lane)=>({q,choice,lane,x:lanes[lane],y:56}));const maxWords=Math.max(...choices.map(i=>String(q.choices[i]).trim().split(/\s+/).length));const fallMs=Math.max(3500,maxWords*250);fallSpeed=(H-122)/(fallMs/1000);phase='read';phaseUntil=now+1500;document.getElementById('dropQuestion').textContent=q.text;document.getElementById('dropPhase').textContent='Read the question'}
