  const animateReflow=(before)=>{if(!motionAllowed())return;[...lane.querySelectorAll('.drag-card')].forEach(card=>{const a=before.get(card),b=card.getBoundingClientRect();if(!a)return;const dy=a.top-b.top;if(Math.abs(dy)>1)card.animate([{transform:`translateY(${dy}px)`},{transform:'translateY(0)'}],{duration:200,easing:'cubic-bezier(.2,.7,.2,1)'})})};
