function renderQuestionSession(c){
  clearConfidenceCountdown();const s=state.currentSession,q=currentQuestion(),mount=document.getElementById('studyMount');if(!s||!q){renderStudyStart(c);return}
  document.querySelector('.course-shell')?.classList.add('quiz-active');
  const committed=s.committedEventId?state.attempts.find(e=>e.eventId===s.committedEventId):null;
  const top=`<div class="study-top"><div><span class="eyebrow">${esc(topicName(c,q.topicId))}</span> <span class="tiny">Question ${s.index+1} of ${s.questionIds.length}</span></div><div class="study-top-actions"><div id="quizTimerDock" class="quiz-timer-dock${state.showStudyTimer?'':' hidden'}"><span class="quiz-inline-clock" id="quizInlineClock" role="timer" aria-label="Elapsed study time" data-status="${esc(s.status||'active')}">${esc(formatElapsed(activeSessionElapsed(s)))}</span></div><div class="session-save-state">Saved ${esc(relativeSaved(s.lastSavedAt))}</div><button class="btn small quiz-pause-btn" id="pauseSession" aria-label="${s.status==='paused'?'Resume quiz':'Pause quiz'}"><span aria-hidden="true">${s.status==='paused'?'▶':'Ⅱ'}</span>${s.status==='paused'?'Resume':'Pause'}</button></div></div><div class="progressline"><i style="width:${((s.index+1)/s.questionIds.length)*100}%"></i></div>`;
  if(committed)mount.innerHTML=`<div class="study-column">${top}<div class="question-stage swap" id="questionStage"></div></div>`;
  else mount.innerHTML=`<div class="study-column">${top}${state.showAdaptiveReason!==false?`<div class="adaptive-reason"><strong>Personalised review:</strong> ${esc(adaptiveReason(q))}</div>`:''}<h2 class="question-title">${esc(questionText(s,q))}</h2><div class="question-stage swap" id="questionStage"></div></div>`;
  document.getElementById('pauseSession').addEventListener('click',()=>{if(s.status==='paused')resumeSession(s);else pauseSession(s);renderQuestionSession(c)});
  const stage=document.getElementById('questionStage');if(committed){renderFeedback(c,q,committed);return}
  if(s.status==='paused'){stage.innerHTML='<div class="notice">Quiz paused. Resume when you are ready to continue.</div>';return}
  const p=questionPresentation(s,q);stage.innerHTML=`<div class="answers" id="answerStack">${p.choiceOrder.map((orig,display)=>`<button class="answer" data-answer="${orig}">${String.fromCharCode(65+display)}. ${esc(q.choices[orig])}</button>`).join('')}</div>`;
  stage.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>showConfidenceInPlace(c,q,b)));if(Number.isInteger(s.pendingAnswer)){const pending=stage.querySelector(`[data-answer="${s.pendingAnswer}"]`);if(pending)showConfidenceInPlace(c,q,pending,true)}
