function renderFeedback(c,q,e){
  const stage=document.getElementById('questionStage');if(!stage)return;if(e.correct===false&&!e.feedbackViewedAt){e.feedbackViewedAt=new Date().toISOString();silentSave()}const paused=state.currentSession?.status==='paused',nextLabel=paused?'Resume to continue':state.currentSession?.index<(state.currentSession?.questionIds.length-1)?'Next question':'Finish quiz';
  stage.innerHTML=`<div class="feedback"><div class="feedback-top"><div><div class="eyebrow">${e.correct?'Correct':'Review'}</div><h3 class="${e.correct?'result-good':'result-bad'}">${esc(feedbackHeadline(e,q))}</h3></div><button class="btn primary feedback-next" data-ui-sound="advance" id="nextQuestion" ${paused?'disabled aria-disabled="true"':''}><span>${nextLabel}</span><span class="feedback-next-arrow" aria-hidden="true">→</span></button></div><p class="annotatable-text" data-annotation-surface="q:${esc(q.id)}">${annotationTextHtml(q.explanation,`q:${q.id}`)}</p>${q.example?`<details class="feedback-example"><summary>See an example</summary><p>${esc(q.example)}</p></details>`:''}<div class="quiz-study-tools"><span>Select text if you want to explain or mark it.</span><div class="quiz-study-tool-actions"><button class="annotation-shortcut selection-tools-fallback" type="button" data-use-selected-text><span class="shortcut-icon" aria-hidden="true">⌁</span>Explain or mark</button><button class="context-tip-icon" type="button" data-context-tip="annotation" aria-label="What can I do with selected text?">?</button></div>${annotationListMarkup(`q:${q.id}`)}</div>${plainSourceOrigin(q)}<details class="question-options"><summary>Question options</summary><div class="question-feedback-actions"><button class="btn small dislike-question" id="dislikeQuestion">I don’t like this question</button><button class="btn small" id="reportQuestion">Something seems wrong</button></div><div id="reportInline"></div></details></div>`;
  document.getElementById('nextQuestion').addEventListener('click',()=>advanceSession(c));document.getElementById('reportQuestion').addEventListener('click',()=>showReportForm(q));document.getElementById('dislikeQuestion')?.addEventListener('click',()=>showReportForm(q,'I don’t like this question'));document.querySelector('[data-open-study-lesson]')?.addEventListener('click',()=>openStudyLesson(c,q));bindAnnotationSurfaces()
}

function commitAttempt(c,q,confidence){
  const s=state.currentSession;if(!s||s.committedEventId)return;const ans=s.pendingAnswer;const prior=state.attempts.filter(x=>x.courseId===c.id&&x.questionId===q.id).length;const e={eventId:'attempt-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),learnerId:state.deviceId,courseId:c.id,topicId:q.topicId,objectiveId:q.objectiveId,questionId:q.id,questionVersion:q.version,sessionId:s.sessionId,answer:ans,correct:ans===q.answer,confidence,hintUsed:false,answerPreviouslyExposed:false,attemptKind:prior?'retry':'first',answeredAt:new Date().toISOString(),clockSource:'device',sourceVersionIds:q.sourceVersionIds,scheduleRuleVersion:SCHEDULE_RULE_VERSION};state.attempts.push(e);s.attemptEventIds.push(e.eventId);s.committedEventId=e.eventId;delete s.pendingAnswer;if(state.onboarding.answerHintCount<2)state.onboarding.answerHintCount++;persist('attempt recorded');playUiSound(e.correct?'success':'press');renderQuestionSession(c);announce(e.correct?'Correct. Feedback is ready.':'Not quite. Feedback is ready.')
}

function annotationTextHtml(value,surfaceId){
  const raw=String(value??''),hostHash=annotationAnchorHash(raw),anns=(state.annotations||[]).filter(a=>a.surfaceId===surfaceId&&(a.type==='highlight'||a.type==='circle')).slice().sort((a,b)=>String(b.quote).length-String(a.quote).length);
  if(!anns.length)return esc(raw);
  const ranges=[];anns.forEach(a=>{const q=String(a.quote||'').trim();if(!q)return;if(a.anchorHash&&a.anchorHash!==hostHash)return;let from=0,occ=0,target=Number.isInteger(a.anchorOccurrence)?a.anchorOccurrence:0;while(from<raw.length){const i=raw.indexOf(q,from);if(i<0)break;const j=i+q.length;if(occ===target){if(!ranges.some(r=>i<r.end&&j>r.start))ranges.push({start:i,end:j,type:a.type,id:a.id,color:a.color});break}occ++;from=j}});
  if(!ranges.length)return esc(raw);ranges.sort((a,b)=>a.start-b.start);let out='',pos=0;ranges.forEach(r=>{out+=esc(raw.slice(pos,r.start));const cls=r.type==='circle'?'annotation-circle':'annotation-highlight',style=r.type==='highlight'?` style="background:${safeHighlightColor(r.color||state.annotationPrefs?.highlightColor)}"`:'';out+=`<span class="${cls}" data-annotation-id="${esc(r.id)}"${style}>${esc(raw.slice(r.start,r.end))}</span>`;pos=r.end});out+=esc(raw.slice(pos));return out
}

function annotationListMarkup(surfaceId){
  const anns=(state.annotations||[]).filter(a=>a.surfaceId===surfaceId).slice(-4).reverse();if(!anns.length)return '';
  return `<div class="annotation-list">${anns.map(a=>`<div class="annotation-chip" data-annotation-chip="${esc(a.id)}"><span>${a.type==='highlight'?`<i style="display:inline-block;width:10px;height:10px;border-radius:3px;background:${safeHighlightColor(a.color||state.annotationPrefs?.highlightColor)};margin-right:5px"></i>`:''}<strong>${a.type==='circle'?'Circled':'Highlighted'}</strong> · “${esc(a.quote)}”<small class="annotation-orphan-note hidden">Wording changed since you marked this.</small></span><button type="button" data-delete-annotation="${esc(a.id)}" aria-label="Delete annotation">Delete</button></div>`).join('')}</div>`
}

function refreshAnnotationSurface(surfaceId){
  if(!surfaceId)return;const selector=`.annotatable-text[data-annotation-surface="${CSS.escape(surfaceId)}"]`,els=[...document.querySelectorAll(selector)];if(!els.length)return;
  els.forEach(el=>{const raw=el.textContent||'';el.innerHTML=annotationTextHtml(raw,surfaceId);delete el.dataset.annotationBound});
  const containers=new Set(els.map(el=>el.closest('.class-note-section,.source-item,.feedback')).filter(Boolean));
  containers.forEach(container=>{const hint=container.querySelector('.annotation-hint');if(!hint)return;hint.querySelector('.annotation-list')?.remove();hint.insertAdjacentHTML('beforeend',annotationListMarkup(surfaceId));});
  bindAnnotationSurfaces();
}

function languageHelpForSelection(quote){
  const key=normaliseLanguageKey(quote),hit=LANGUAGE_HELP[key];
  if(hit)return `<strong>Plain language</strong><br>${esc(hit.plain)}<br><span class="tiny">Possible alternatives: ${esc(hit.synonyms)}. Language help only — course/legal meaning can be more specific.</span>`;
  const matches=[];Object.entries(LANGUAGE_HELP).forEach(([term,info])=>{if(term.length>2&&key.includes(term)&&!matches.some(x=>x.term===term))matches.push({term,...info})});
  if(matches.length)return `<strong>Break this wording down</strong>${matches.slice(0,4).map(x=>`<div style="margin-top:7px"><b>${esc(x.term)}</b> — ${esc(x.plain)}<div class="tiny">Alternatives: ${esc(x.synonyms)}</div></div>`).join('')}<div class="tiny" style="margin-top:8px">This is vocabulary help, not a substitute for the reviewed course/legal source.</div>`;
  return `<strong>Explain this wording</strong><br><span class="tiny">This selection is saved correctly, but a source-backed explainer for this exact phrase is not connected yet. The production version should explain the whole selected phrase and separate vocabulary help from course/legal authority.</span>`
}

function saveAnnotation(type,color){
  const p=pendingStudySelection;if(!p)return;const before=annotationSnapshot(),surfaceId=p.surfaceId,existing=p.annotationId&&(state.annotations||[]).find(a=>a.id===p.annotationId);if(existing){existing.type=type;existing.color=type==='highlight'?safeHighlightColor(color||existing.color||state.annotationPrefs?.highlightColor):undefined;existing.updatedAt=new Date().toISOString()}else{const id='ann-'+Date.now()+'-'+Math.random().toString(36).slice(2,5);state.annotations.push({id,type,quote:p.quote,surfaceId:p.surfaceId,courseId:state.activeCourseId||null,route:p.route,anchorHash:p.anchorHash||null,anchorOccurrence:Number.isInteger(p.anchorOccurrence)?p.anchorOccurrence:0,color:type==='highlight'?safeHighlightColor(color||state.annotationPrefs?.highlightColor):undefined,createdAt:new Date().toISOString()})}if(!persist(`${type} annotation saved`))return;closeAnnotationPopover();refreshAnnotationSurface(surfaceId);offerAnnotationUndo(before,surfaceId,type==='circle'?'Circle saved.':'Highlight saved.');showToast(type==='circle'?'Circled selection saved.':'Highlight saved.')
}

