function seedRewardCandidate(c,s,attempts,growth){
  const correct=attempts.filter(a=>a.correct).length,total=attempts.length;
  if(!total)return {key:null,amount:0,label:'No quiz answers recorded'};
  if(!correct)return {key:null,amount:0,label:`0 of ${total} correct · wrong answers earn 0 Seeds`};
  return {key:`quiz-score|${s.sessionId}`,amount:correct,label:`${correct} of ${total} correct · 1 Seed per correct answer`}
}

