function currentLessons(c){return [
{id:'sources',title:'Sources of police powers',sourceLabel:'PFP 207 Quiz 1 Study Guide · pp. 1–6',intro:'Police power comes from the constitutional structure, statutes and delegated rules, and common law/case law. The Charter limits how that power can be exercised.',more:'This chapter connects federal and provincial roles, places police in the executive branch, and groups important Charter rules around ss. 7–12. Cases such as Collins, Feeney, Mann, Grant, Spencer, Fearon, Singh, Brydges and Bartle connect those rules to concrete examples.',points:['Federal Parliament creates criminal law; provinces enforce and prosecute it.','Police are part of the executive branch; courts interpret and review police conduct.','Police-power sources here are statutes, regulations/by-laws, and common law/case law.','The Charter can limit police practices; this chapter focuses on ss. 7–12 plus remedies under s. 24.'],questions:['q1','q6','q7','q8']},
{id:'arrest',title:'Arrest powers and release decisions',sourceLabel:'PFP 207 Quiz 1 Study Guide · pp. 7–14',intro:'Chapter 2 centres on Criminal Code arrest authority, the limits on arrest, reasonable grounds, offence classification, release, investigative detention, warrants, age and citizen arrest.',more:'This chapter distinguishes reasonable suspicion from reasonable grounds, explains the subjective and objective components of reasonable grounds, and covers when s. 495(2) can require release for s. 553, hybrid and summary matters. It also separates voluntary accompaniment, investigative detention and arrest.',points:['Reasonable grounds require both a subjective belief and an objective basis.','Hybrid offences are treated as indictable until the Crown elects the procedure.','Investigative detention is not arrest and uses the lower reasonable-suspicion standard.','The lawful arrest sequence used here is: identify, control, appropriate force, under arrest, why, counsel.'],questions:['q2','q5','q9','q10','q11','q12']},
{id:'residence',title:'Location of arrest and Feeney laws',sourceLabel:'PFP 207 Quiz 1 Study Guide · pp. 15–22',intro:'Chapter 3 separates dwelling-houses from other places and then asks what authority police have to enter a dwelling-house to arrest.',more:'This chapter traces Eccles to Feeney and the Criminal Code entry provisions, then compares Feeney warrants, exigent circumstances, hot pursuit, 911/life-safety entry, consent and the announcement rule. Strong arrest grounds do not by themselves create authority to enter a home.',points:['A dwelling-house includes a place used temporarily or permanently as a residence.','A Feeney warrant generally requires reasonable grounds for the indictable offence and reasonable grounds the person is or will be inside.','Hot pursuit is a common-law exception; exigent entry is addressed separately in s. 529.3.','Announcement is framed as identity, purpose and a request for entry unless a lawful exception applies.'],questions:['q3','q4','q13','q14','q15']}
]}

function renderSources(c,main,mode='adaptive'){
  if(c.id!=='pfp207'){main.innerHTML=courseHead(c,'Learn')+`<div class="notice">No lesson records are attached to this example.</div>`;return}
  mode=['adaptive','chapters','all'].includes(mode)?mode:'adaptive';const lessons=currentLessons(c),tabs=`<div class="learn-tabs" role="tablist" aria-label="Learn view"><a class="learn-tab" aria-current="${mode==='adaptive'?'page':'false'}" href="#/course/${c.id}/sources/adaptive">Adaptive</a><a class="learn-tab" aria-current="${mode==='chapters'?'page':'false'}" href="#/course/${c.id}/sources/chapters">Chapters</a><a class="learn-tab" aria-current="${mode==='all'?'page':'false'}" href="#/course/${c.id}/sources/all">All topics</a></div><div class="learn-mode-note">${mode==='adaptive'?'<strong>Adaptive</strong> changes the order based on what you have missed, remembered, and revisited. It does not hide the rest of the course.':mode==='chapters'?'<strong>Chapters</strong> keeps the course in class order. Open a chapter to read the lesson currently mapped inside it.':'<strong>All topics</strong> shows every current lesson without reordering.'}</div>`;
  const bindLessonUi=()=>{main.querySelectorAll('[data-lesson-expand]').forEach(btn=>btn.addEventListener('click',()=>{const more=document.getElementById(`lesson-more-${btn.dataset.lessonExpand}`),open=more.classList.toggle('expanded');btn.textContent=open?'Show summary only':'Show detailed lesson'}));bindAnnotationSurfaces()};
  if(mode==='chapters'){
    const names=['Chapter 1 · Sources of Police Powers','Chapter 2 · Arrest Powers','Chapter 3 · Location of Arrest and Feeney Laws'];
    main.innerHTML=courseHead(c,'Learn')+tabs+`<p class="lede">Browse the course in class order without leaving the page.</p><div class="chapter-grid">${lessons.map((lesson,i)=>`<details class="chapter-card"><summary><strong>${esc(names[i]||`Chapter ${i+1}`)}</strong><span>Open chapter</span></summary><div class="chapter-body">${lessonMarkup(lesson,c,'all',i)}</div></details>`).join('')}</div>`;bindLessonUi();return
  }
  const lessonPriority=l=>l.questions.length?Math.max(...l.questions.map(id=>QUESTIONS[id]).filter(Boolean).map(priorityScore)):-1;const ordered=mode==='adaptive'?[...lessons].sort((a,b)=>lessonPriority(b)-lessonPriority(a)):lessons;
  main.innerHTML=courseHead(c,'Learn')+tabs+`<div class="reading-rail"><p class="lede">${mode==='adaptive'?'Start with the lesson that needs attention now, then move through the rest when you want.':'Browse every current lesson without adaptive ordering.'}</p><p class="subtle"><strong>Current source:</strong> these lesson previews are built from the attached PFP 207 course material. They are still not labelled instructor-approved inside StudyGrid.</p></div><div class="annotation-page-guide"><span>Select wording in any lesson. Explain, highlight, circle, ask your teacher or share only when you need it.</span>${annotationShortcutMarkup()}</div><div class="source-list">${ordered.map((x,i)=>lessonMarkup(x,c,mode,i)).join('')}</div>`;bindLessonUi()
}

