function setupPlanVineInteractions(){
  root.querySelectorAll('.plan-mode').forEach(card=>{
    if(!motionAllowed())return;
    const intensity=card.dataset.intensity;
    const duration={quick:3400,focus:4800,deep:6800}[intensity]||4200;
    const pieces=[...card.querySelectorAll('.vine-stem,.vine-tendril,.vine-leaf,.vine-node')];
    const animations=pieces.map(el=>{
      const isLeaf=el.classList.contains('vine-leaf')||el.classList.contains('vine-node');
      const layer=el.classList.contains('vine-layer-3')?2:el.classList.contains('vine-layer-2')?1:0;
      const delay=isLeaf?duration*(Number(el.dataset.delay||.42)+layer*.08):layer*duration*.16;
      const keyframes=isLeaf
        ?[{opacity:0,transform:`${el.getAttribute('transform')||''} scale(.1)`},{opacity:.94,transform:el.getAttribute('transform')||'scale(1)'}]
        :[{strokeDashoffset:1,opacity:.04},{strokeDashoffset:0,opacity:layer===2?.88:layer===1?.82:.76}];
      const anim=el.animate(keyframes,{duration:isLeaf?760:duration*(1-layer*.12),delay,fill:'both',easing:isLeaf?'cubic-bezier(.22,.68,0,1)':'cubic-bezier(.16,.74,.18,1)'});
      anim.pause();anim.currentTime=0;return anim
    });
    const grow=()=>animations.forEach(a=>{a.playbackRate=1;a.play()});
    const retract=()=>animations.forEach(a=>{if(a.currentTime===null||a.currentTime<=0){a.pause();a.currentTime=0}else{a.playbackRate=-1;a.play()}});
    card.addEventListener('pointerenter',grow);card.addEventListener('pointerleave',retract);card.addEventListener('focus',grow);card.addEventListener('blur',retract)
  })
}

