  const moreSettings=`<div class="setting"><div><strong>Garden cues</strong><span class="setting-copy">Small gardening moments during longer study.</span></div><button type="button" class="toggle" id="gardenToggle" aria-pressed="${state.gardenCues}">${state.gardenCues?'On':'Off'}</button></div><div class="setting"><div><strong>Personalised review notes</strong><span class="setting-copy">Show why StudyGrid included a question in your review.</span></div><button type="button" class="toggle" id="adaptiveToggle" aria-pressed="${state.showAdaptiveReason!==false}">${state.showAdaptiveReason!==false?'On':'Off'}</button></div><div class="setting"><div><strong>Feedback prompts</strong><span class="setting-copy">Preference retained for future task-specific beta prompts. This build uses the persistent global Feedback control instead of extra Study-page invitations.</span></div><button type="button" class="toggle" id="feedbackPromptToggle" aria-pressed="${state.sessionFeedbackPrompts!==false}">${state.sessionFeedbackPrompts!==false?'On':'Off'}</button></div><div class="setting"><div><strong>Interface sounds</strong><span class="setting-copy">Short, quiet feedback sounds on selected study actions. You can turn them off at any time.</span></div><button type="button" class="toggle" id="soundToggle" aria-pressed="${state.interfaceSounds!==false}">${state.interfaceSounds!==false?'On':'Off'}</button></div><div class="setting"><div><strong>My highlight colour</strong><span class="setting-copy">Used when you choose Highlight in lessons and quiz explanations.</span></div><div class="row"><input id="profileHighlightColor" type="color" aria-label="My highlight colour" value="${safeHighlightColor(state.annotationPrefs?.highlightColor)}"><button type="button" class="btn small" id="saveProfileHighlightColor">Save colour</button></div></div><div class="setting"><div><strong>Example history</strong><span class="setting-copy">Opt in to labelled demo attempts for testing. Off by default.</span></div><button type="button" class="toggle" id="exampleHistoryToggle" aria-pressed="${state.showExampleHistory}">${state.showExampleHistory?'On (example history)':'Off'}</button></div><div class="setting"><div><strong>Study tips</strong><span class="setting-copy">Show the short first-use hints again.</span></div><button type="button" class="btn small" id="resetTips">Show tips again</button></div><div class="setting"><div><strong>New instructor material</strong><span class="setting-copy">Choose what happens when your instructor publishes notes, recordings or transcripts for your class.</span></div><select class="material-pref-select" id="teacherMaterialMode"><option value="auto" ${state.materialPreferences?.teacherMaterialMode==='auto'?'selected':''}>Add automatically</option><option value="ask" ${(state.materialPreferences?.teacherMaterialMode||'ask')==='ask'?'selected':''}>Ask me first</option><option value="off" ${state.materialPreferences?.teacherMaterialMode==='off'?'selected':''}>Do not add automatically</option></select></div><div class="setting"><div><strong>Instructor update notifications</strong><span class="setting-copy">Show a class update when an instructor publishes new material.</span></div><button type="button" class="toggle" id="teacherNotificationToggle" aria-pressed="${state.materialPreferences?.teacherNotifications!==false}">${state.materialPreferences?.teacherNotifications!==false?'On':'Off'}</button></div><div class="setting"><div><strong>Product tour</strong><span class="setting-copy">Replay the short, interactive introduction to Learn, Test, Support and your Tree.</span></div><a class="btn small" href="#/tour">Replay tour</a></div>`;
  root.innerHTML=`<div class="page profile-settings-page"><div class="row spaced"><div><div class="eyebrow">Profile · Settings</div><h1 class="section-title">Settings</h1><p class="lede">Appearance and study preferences stay here instead of crowding your profile.</p></div><a class="btn" href="#/profile">Back to profile</a></div><div class="settings-grid">${primarySettings}<details class="settings-more" id="moreStudySettings"><summary>More study settings</summary><div class="settings-more-grid">${moreSettings}</div></details></div></div>`;
  root.querySelectorAll('.setting').forEach((row,i)=>{const title=row.querySelector('strong')?.textContent?.trim();if(!title)return;const titleId=`setting-title-${i}`;row.querySelector('strong')?.setAttribute('id',titleId);row.querySelectorAll('button.toggle').forEach(btn=>btn.setAttribute('aria-labelledby',titleId))});
