  document.getElementById('motionToggle')?.addEventListener('click',()=>{state.lessMotion=!state.lessMotion;persist('motion preference changed');applyPrefs();rerenderProfileSettingsPreservingFocus('motionToggle')});
  document.getElementById('resetTips')?.addEventListener('click',()=>{state.onboarding={...state.onboarding,answerHintCount:0,treeHintSeen:false,laterHintSeen:false,scenarioSeen:false};persist('study tips reset');showToast('Study tips will appear again.')});
