  document.getElementById('teacherNotificationToggle')?.addEventListener('click',()=>{state.materialPreferences={...(state.materialPreferences||{}),teacherNotifications:state.materialPreferences?.teacherNotifications===false};persist('teacher notification preference changed');rerenderProfileSettingsPreservingFocus('teacherNotificationToggle')});
  document.getElementById('soundToggle')?.addEventListener('click',()=>{state.interfaceSounds=state.interfaceSounds===false;persist('interface sound preference changed');rerenderProfileSettingsPreservingFocus('soundToggle');if(state.interfaceSounds!==false)playUiSound('press')});
