  document.getElementById('gardenToggle')?.addEventListener('click',()=>{state.gardenCues=!state.gardenCues;persist('garden cue preference changed');rerenderProfileSettingsPreservingFocus('gardenToggle');syncStudyTimer()});
  document.getElementById('adaptiveToggle')?.addEventListener('click',()=>{state.showAdaptiveReason=!state.showAdaptiveReason;persist('adaptive reason preference changed');rerenderProfileSettingsPreservingFocus('adaptiveToggle')});
  document.getElementById('feedbackPromptToggle')?.addEventListener('click',()=>{state.sessionFeedbackPrompts=!state.sessionFeedbackPrompts;persist('feedback prompt preference changed');rerenderProfileSettingsPreservingFocus('feedbackPromptToggle')});
