function renderInventory(){
  const owned=new Set(state.avatarInventory||[]);
  root.innerHTML=`<div class="page"><div class="row spaced"><div><div class="eyebrow">Profile · Inventory</div><h1 class="section-title">Your inventory</h1><p class="lede">A dedicated wardrobe space for your avatar and earned cosmetics.</p></div><a class="btn" href="#/profile">Back to profile</a></div><div class="inventory-stage"><div class="inventory-stage-inner"><div class="inventory-stage-orbit" aria-label="3D inventory preview placeholder"><div class="inventory-stage-avatar"></div></div><strong>Interactive 3D wardrobe stage</strong><p class="subtle">The final version will let you rotate your character, preview an item before equipping it, and inspect cosmetics in one focused space. This placeholder does not pretend the 3D renderer is connected yet.</p><div class="coin-pill"><span class="coin-dot"></span>${state.coinBalance||0} Seeds available</div></div></div><div class="eyebrow">Owned items</div><div class="avatar-inventory">${owned.size?[...owned].map(id=>{const item=AVATAR_SHOP.find(x=>x.id===id);return item?`<div class="inventory-item"><strong>${esc(item.name)}</strong><span>${esc(item.kind)} · owned</span><button class="btn small" data-equip-item="${esc(id)}">${state.equippedAvatarItems?.includes(id)?'Equipped':'Equip'}</button></div>`:''}).join(''):'<div class="notice">No purchased cosmetic items on this device yet.</div>'}</div><div class="eyebrow" style="margin-top:26px">Available cosmetics</div><div class="avatar-shop-grid">${AVATAR_SHOP.map(item=>`<div class="shop-item"><strong>${esc(item.name)}</strong><span>${esc(item.kind)}</span><div class="shop-cost"><div class="coin-pill"><span class="coin-dot"></span>${item.cost} Seeds</div><button class="btn small" data-buy-item="${esc(item.id)}" ${owned.has(item.id)?'disabled':''}>${owned.has(item.id)?'Owned':'Buy'}</button></div></div>`).join('')}</div></div>`;
  root.querySelectorAll('[data-buy-item]').forEach(b=>b.addEventListener('click',()=>purchaseAvatarItem(AVATAR_SHOP.find(x=>x.id===b.dataset.buyItem),renderInventory)));
  root.querySelectorAll('[data-equip-item]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.equipItem;state.equippedAvatarItems=state.equippedAvatarItems||[];state.equippedAvatarItems=state.equippedAvatarItems.includes(id)?state.equippedAvatarItems.filter(x=>x!==id):[...state.equippedAvatarItems,id];persist('avatar item equipped');renderInventory()}))
}

function equipAppearance(id,button){
  state.equippedAppearance=id;
  document.documentElement.style.setProperty('--accent',id==='firstlight'?'#C89A4B':id==='seedmark'?'#817354':'#829F78');
  if(persist('appearance equipped')){
    const finish=()=>{announce(`${APPEARANCES[id].name} equipped.`);if(parseRoute().parts[0]==='profile')renderProfile()};
    if(id==='firstlight'&&motionAllowed()){
      button.classList.remove('previewing');void button.offsetWidth;button.classList.add('previewing');
      showToast('First Light equipped — watch the preview.');
      setTimeout(()=>{button.classList.remove('previewing');finish()},1900)
    }else{
      showToast(`${APPEARANCES[id].name} equipped.`);
      setTimeout(finish,220)
    }
  }
}

function renderScenario(c,main){
  if(c.id!=='pfp207'){main.innerHTML=courseHead(c,'Scenario lab')+`<div class="notice">No scenario is attached.</div>`;return}
  main.innerHTML=courseHead(c,'Scenario lab')+`<div class="scenario"><div class="notice scenario-source-note">Practice scenario · outside assessed study. Legal/course correctness stays provisional until reviewed instructor or authoritative sources are attached.</div><div class="scenario-shell"><div><div id="scenarioIntroMount"></div><div id="scenarioMount"></div></div><aside class="scenario-context" aria-label="Scenario context"><div class="scenario-context-kicker">Current scene</div><strong id="sceneLabel">Choose a storyline</strong><div class="scenario-step-track" id="scenarioStepTrack"><i class="active"></i><i></i><i></i></div><p class="subtle" id="scenarioContextCopy">The story gives the decisions context. The legal/course debrief remains provisional until source review is connected.</p></aside></div></div>`;
  const intro=document.getElementById('scenarioIntroMount');
  if(!state.activeScenario){intro.innerHTML=`<div class="scenario-intro"><div class="eyebrow">Scenario Lab</div><h3>Choose a story, then make the calls.</h3><p class="subtle">These are fictional practice stories. They use the same provisional decision points while the 3D scene system is being built.</p><div class="scenario-story-picker">${Object.values(SCENARIO_STORIES).map((story,i)=>`<button class="scenario-story-card" data-story-id="${story.id}"><strong>${esc(story.name)}</strong><span>${esc(story.role)} · ${esc(story.location)}</span></button>`).join('')}</div></div>`;document.getElementById('scenarioMount').innerHTML='';intro.querySelectorAll('[data-story-id]').forEach(b=>b.addEventListener('click',()=>{state.onboarding.scenarioSeen=true;persist('scenario story chosen');intro.innerHTML='';startScenario(true,b.dataset.storyId)}))}else{intro.innerHTML='';startScenario(false,state.activeScenario.storyId)}
}

function renderScenarioStep(){
  const s=window.__sgScenario,m=document.getElementById('scenarioMount');if(!m)return;const story=SCENARIO_STORIES[s.storyId]||SCENARIO_STORIES.harbour,label=document.getElementById('sceneLabel'),track=document.getElementById('scenarioStepTrack'),context=document.getElementById('scenarioContextCopy');if(s.step>=SCENARIO_STEPS.length){renderDebrief(m,s);return}const x=SCENARIO_STEPS[s.step];if(label)label.textContent=`${story.location} · ${x.visual}`;if(context)context.textContent=`${story.role}: ${story.steps[s.step]||story.brief}`;if(track)[...track.children].forEach((dot,i)=>dot.classList.toggle('active',i<=s.step));const saved=s.notes[s.step]||'';
  m.innerHTML=`<section class="scenario-stage"><div class="scenario-progress-label">${esc(story.name)} · Decision ${s.step+1} of ${SCENARIO_STEPS.length}</div><div class="scenario-brief"><strong>${s.step===0?'Dispatch & approach':'Story continues'}</strong>${esc(s.step===0?story.brief:story.steps[s.step])}</div><h3>${esc(x.title)}</h3><p class="subtle">${esc(x.text)}</p><div class="scenario-choices">${x.choices.map((c,i)=>`<button class="scenario-choice" data-scenario-choice="${esc(c[1])}" data-choice-index="${i}"><span>${String.fromCharCode(65+i)}</span><strong>${esc(c[0])}</strong></button>`).join('')}</div><details class="scenario-note-disclosure"><summary>Add a note</summary><div class="scenario-note"><p class="tiny">Optional. Notes stay on this device in the preview.</p><textarea id="scenarioNotes" placeholder="What did you notice or why did you choose this?">${esc(saved)}</textarea></div></details><div class="row"><button class="btn" id="scenarioExplain">Open debrief early</button><button class="btn" id="resetScenario">Choose another story</button></div></section>`;
  document.getElementById('scenarioNotes')?.addEventListener('input',e=>{s.notes[s.step]=e.target.value;state.activeScenario=s});document.getElementById('scenarioNotes')?.addEventListener('blur',()=>persist('scenario notes saved'));document.getElementById('resetScenario')?.addEventListener('click',()=>{state.activeScenario=null;persist('scenario reset');renderScenario(COURSES.pfp207,document.getElementById('courseMain'))});m.querySelectorAll('[data-scenario-choice]').forEach(b=>b.addEventListener('click',()=>{s.notes[s.step]=document.getElementById('scenarioNotes')?.value||s.notes[s.step]||'';s.path.push({step:s.step,choice:b.dataset.scenarioChoice,index:Number(b.dataset.choiceIndex),note:s.notes[s.step]});s.step++;state.activeScenario=s;persist('scenario progress');renderScenarioConsequence(m,s)}));document.getElementById('scenarioExplain').addEventListener('click',()=>{s.shownExplanation=true;state.activeScenario=s;persist('scenario debrief opened');renderDebrief(m,s)})
}

function renderScenarioConsequence(m,s){
  const last=s.path.at(-1)?.choice;
  const copy={
    pursue:'The chase stays continuous and the visual moves with you toward the entry.',
    contain:'The scene changes from pursuit to containment. Time passes while authority is considered.',
    'warrant-assumption':'You enter on an assumption about entry authority. The scenario keeps going, but that decision is now marked for the debrief.',
    delay:'The immediate chase is gone. Calling the later entry “hot pursuit” is now part of the problem the debrief will revisit.',
    'full-announce':'The entry record now includes identity, purpose, and the request for entry.',
    'police-only':'The entry continues, but “Police!” alone is marked for review in the debrief.',
    'name-only':'The entry continues without a complete police/purpose announcement in the current prototype.',
    'serious-offence':'The seriousness of the offence is recorded as your reason for skipping the announcement; the debrief will test that reasoning.',
    release:'The release route is recorded and the scene moves to the end state.',
    'arrest-anyway':'The arrest is recorded despite the release requirement in the current prototype rule.',
    'arrest-first':'The arrest is made first; the necessity question is deferred until afterward.',
    'wait-crown':'The officer delays the decision waiting for the Crown election.'
  }[last]||'Your decision is recorded. The scenario continues before the explanation.';
  m.innerHTML=`<section class="scenario-stage"><div class="eyebrow">Consequence</div><h3>${esc(copy)}</h3><p class="subtle">Your choice and note stay in the path record. See what happened first; the debrief comes after the scenario unless you choose to open it early.</p><div class="row"><button class="btn primary" id="continueScenario">Continue</button><button class="btn linkish" id="explainNow">Open debrief early</button></div></section>`;
  document.getElementById('continueScenario').addEventListener('click',renderScenarioStep);
  document.getElementById('explainNow').addEventListener('click',()=>renderDebrief(m,s))
}

function renderDebrief(m,s){
  const bad=['contain','warrant-assumption','delay','police-only','name-only','serious-offence','arrest-anyway','arrest-first','wait-crown'];
  const first=s.path.find(x=>bad.includes(x.choice));
  const choiceLabel=x=>{const step=SCENARIO_STEPS[x.step],choice=step?.choices?.[x.index];return choice?.[0]||x.choice};const turning=first?`Decision ${first.step+1}: ${choiceLabel(first)}`:'No staged turning point in the completed path.';
  m.innerHTML=`<section class="debrief"><div class="eyebrow">Debrief · ${esc((SCENARIO_STORIES[s.storyId]||SCENARIO_STORIES.harbour).name)}</div><h2 class="section-title">First turning point: ${esc(turning)}</h2><p>${scenarioDebriefText(first?.choice)}</p><div class="scenario-path"><strong>Your path</strong><ol>${s.path.map(x=>`<li>${esc(choiceLabel(x))}${x.note?`<div class="tiny">Your note: ${esc(x.note)}</div>`:''}</li>`).join('')}</ol></div><details class="source-drawer"><summary>Where this comes from</summary><div class="source-record"><strong>Prototype scenario source record</strong><div>Built from v5 prototype items <code>q3</code>, <code>q4</code> and <code>q5</code>.</div><div>Source fingerprint: <code>${V5_HASH.slice(0,20)}…</code></div><div>Course-source review is still required before assessed use.</div><div class="source-excerpt-placeholder"><strong>Read the exact source</strong><br>Once a reviewed Criminal Code / RTA / instructor file is linked, the verbatim excerpt and precise locator can appear here without leaving the scenario.</div></div></details><div class="row"><button class="btn primary" id="retryScenario">Try another approach</button><a class="btn" href="#/course/pfp207/study">Back to study</a></div></section>`;
  if(!s.completedAt){s.completedAt=new Date().toISOString();state.scenarioRuns=[...(state.scenarioRuns||[]),JSON.parse(JSON.stringify(s))].slice(-20);state.activeScenario=null;persist('scenario run completed')}document.getElementById('retryScenario').addEventListener('click',()=>startScenario(true))
}

function scenarioDebriefText(x){
  if(x==='contain'||x==='delay')return 'This staged branch is testing whether an immediate continuous pursuit was preserved. It does not certify the legal result without reviewed course-source bindings.';
  if(x==='warrant-assumption')return 'This staged branch is testing whether arrest authority and authority to enter a residence are being treated as the same thing. Exact legal wording must come from reviewed sources.';
  if(['police-only','name-only','serious-offence'].includes(x))return 'The current v5 prototype expects identity, purpose and a request for entry absent an exception. This v6.1 visual scenario still requires exact course-source certification.';
  if(['arrest-anyway','arrest-first','wait-crown'].includes(x))return 'The current v5 prototype treats the release requirement as part of the officer’s arrest decision and keeps Crown election separate. Exact legal/source certification remains required.';
  return 'This staged path did not hit one of the deliberately poor choices before the debrief.'
}

function reportStateMeta(state){
  const s=state||'received';
  const map={received:{label:'Received',tone:'neutral'},being_checked:{label:'Being checked',tone:'warning'},decision_recorded:{label:'Decision recorded',tone:'info'},correction_applied:{label:'Correction applied',tone:'good'},checked_after_change:{label:'Checked after change',tone:'good'},no_change:{label:'No change needed',tone:'neutral'},rejected:{label:'Rejected',tone:'error'}};
  return map[s]||{label:s.replaceAll('_',' '),tone:'neutral'}
}

function questionSourceRef(q){
  if(!q)return 'Source not attached';
  if(q.sourceLabel&&q.sourceLocator)return `${q.sourceLabel} · ${q.sourceLocator}`;
  if(q.sourceLabel)return q.sourceLabel;
  return 'Source not attached';
}

function questionReviewMeta(questionId){
  const r=state.questionReviews?.[questionId];
  if(!r)return {status:'awaiting_review',label:'Awaiting instructor review',tone:'pending'};
  const map={approved:{label:'Approved for this preview',tone:'good'},needs_edit:{label:'Needs edit',tone:'warning'},held:{label:'On hold',tone:'neutral'}};
  return {status:r.status,...(map[r.status]||{label:r.status||'Awaiting instructor review',tone:'pending'})};
}

function questionReviewQueueMarkup(courseId){
  const qs=Object.values(QUESTIONS).filter(q=>q.courseId===courseId),course=COURSES[courseId];
  const groups=(course?.topics||[]).map((t,i)=>{const items=qs.filter(q=>q.topicId===t.id),reports=(state.reports||[]).filter(r=>items.some(q=>q.id===r.questionId)),approved=items.filter(q=>questionReviewMeta(q.id).status==='approved').length,needs=items.filter(q=>questionReviewMeta(q.id).status==='needs_edit').length;const chapter=`Chapter ${i+1} · ${t.name}`;return `<details class="question-review-group"><summary><span>${esc(chapter)}</span><span class="tiny">${items.length} questions${reports.length?` · ${reports.length} flagged`:''}${approved?` · ${approved} approved`:''}${needs?` · ${needs} need edits`:''}</span></summary><div class="question-review-group-body">${items.map(q=>{const m=questionReviewMeta(q.id),qr=(state.reports||[]).filter(r=>r.questionId===q.id),draft=state.questionDrafts?.[q.id];return `<details class="question-review-card"><summary><div><div class="question-review-title">${esc(q.text)}</div><div class="question-review-meta"><span class="tiny">${esc(questionSourceRef(q))}</span>${qr.length?`<span class="status warning">${qr.length} student report${qr.length===1?'':'s'}</span>`:''}${draft?.note?'<span class="status info">Edit note saved</span>':''}</div></div><span class="status ${m.tone} question-review-status">${esc(m.label)}</span></summary><div class="question-review-body"><div class="tiny">Candidate ID ${esc(q.id)} · answer and rationale visible to the instructor only in this review workspace.</div><div style="margin-top:10px">${q.choices.map((c,j)=>`<div class="question-review-choice ${j===q.answer?'correct':''}"><strong>${String.fromCharCode(65+j)}.</strong> ${esc(c)}${j===q.answer?' · correct':''}</div>`).join('')}</div><p class="subtle"><strong>Rationale:</strong> ${esc(q.explanation)}</p><div class="tiny"><strong>Source provenance:</strong> ${esc(questionSourceRef(q))}. Production candidates must keep source identifiers and exact locators before instructor approval.</div>${qr.length?`<div class="question-review-feedback"><strong>Student feedback</strong>${qr.slice().reverse().map(r=>`<div class="question-review-feedback-item"><b>${esc(r.type||'Feedback')}</b>${r.details?` — ${esc(r.details)}`:''}<div class="tiny">${new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(r.createdAt))}</div></div>`).join('')}</div>`:''}<div class="question-review-actions"><button class="btn small" data-question-review="${esc(q.id)}|approved">Approve for preview</button><button class="btn small" data-question-review="${esc(q.id)}|needs_edit">Needs edit</button><button class="btn small" data-question-review="${esc(q.id)}|held">Hold</button></div></div></details>`}).join('')}</div></details>`});
  return `<div class="question-review-list">${groups.join('')}</div>`
}

function ownerAnalyticsMarkup(){
  const events=state.analyticsEvents||[],counts=analyticsEventCounts(),routes=analyticsRouteCounts(),stage=userJourneyStage(),sessions=new Set(events.map(e=>e.sessionId).filter(Boolean)).size,taps=events.filter(e=>e.name==='tap'),maxRoute=Math.max(1,...routes.map(x=>x[1]));
  const dots=taps.slice(-80).map(e=>`<i class="analytics-dot" style="left:${Math.max(2,Math.min(98,Number(e.x)||50))}%;top:${Math.max(4,Math.min(96,Number(e.y)||50))}%"></i>`).join('');
