function runFixtureTests(){
  const base={learnerId:'fixture',courseId:'pfp207',topicId:'arrest',objectiveId:'release-decision',questionVersion:1,answer:1,confidence:1,hintUsed:false,answerPreviouslyExposed:false,clockSource:'test',sourceVersionIds:['fixture:v1'],scheduleRuleVersion:'pilot-1',attemptKind:'first'};
  const e1={...base,eventId:'f1',questionId:'q5a',sessionId:'s1',correct:true,answeredAt:'2026-09-20T12:00:00Z'};
  const immediate={...base,eventId:'f2',questionId:'q5a',sessionId:'s1',correct:true,answeredAt:'2026-09-20T12:10:00Z'};
  const later={...base,eventId:'f3',questionId:'q5a',sessionId:'s2',correct:true,answeredAt:'2026-09-21T13:00:00Z'};
  const repeated={...base,eventId:'f4',questionId:'q5b',sessionId:'s3',correct:true,answeredAt:'2026-09-22T14:30:00Z'};
  const wrongSure={...base,eventId:'f5',questionId:'q5a',sessionId:'s4',correct:false,confidence:2,answeredAt:'2026-09-23T15:00:00Z'};
  const results=[];
  results.push({name:'first correct',expected:'first_correct',actual:deriveObjectiveState([e1]).state});
  results.push({name:'same-session retry is not later memory',expected:'first_correct',actual:deriveObjectiveState([e1,immediate]).state});
  results.push({name:'>=24h new-session correct',expected:'remembered_later',actual:deriveObjectiveState([e1,later]).state});
  results.push({name:'further >=24h different variant',expected:'repeated_later',actual:deriveObjectiveState([e1,later,repeated]).state});
  const fakeQ={...QUESTIONS.q5};const original=objectiveEvents; // priority test uses actual state separately below
  const scoreWrongSure=wrongSure.correct===false&&wrongSure.confidence===2?100:0;
  results.push({name:'wrong + very sure highest provisional priority',expected:100,actual:scoreWrongSure});
  const key1=milestoneKey('fixture','pfp207','first-session-finished',1),key2=milestoneKey('fixture','pfp207','first-session-finished',1);
  results.push({name:'milestone key idempotent',expected:key1,actual:key2});
  return results.map(r=>({...r,pass:r.expected===r.actual}));
}

