function sgReviewMeta(classId,setRevisionId,q){
  const rev=sgQuestionRevision(q,classId,setRevisionId),d=state.questionReviews?.[sgReviewKey(classId,setRevisionId,rev)];
  if(!d)return {status:'needs_review',label:'Needs review',tone:'pending',rev};
  const map={approved:{label:'Approved',tone:'good'},needs_changes:{label:'Needs changes',tone:'warning'},held:{label:'On hold',tone:'neutral'}};
  return {status:d.status,label:map[d.status]?.label||'Needs review',tone:map[d.status]?.tone||'pending',reason:d.reason||'',rev}
}

