function sgSetStatus(chosen,set){
  if(set.seed==='held')return {key:'held',label:'Held',count:0};
  if(set.seed==='published')return {key:'published',label:'Published',count:0};
  if(set.seed==='draft')return {key:'draft',label:'Draft',count:0};
  const metas=set.questionIds.map(id=>QUESTIONS[id]).filter(Boolean).map(q=>sgReviewMeta(chosen.id,set.revisionId,q));
  if(metas.some(m=>m.status==='held'))return {key:'held',label:'Held',count:metas.filter(m=>m.status==='held').length};
  if(metas.some(m=>m.status==='needs_review'||m.status==='needs_changes'))return {key:'needs_review',label:'Needs review',count:metas.filter(m=>m.status!=='approved').length};
  return metas.length&&metas.every(m=>m.status==='approved')?{key:'ready',label:'Ready',count:0}:{key:'draft',label:'Draft',count:0}
}

