applyProfessorCommand(command){if(command?.actor_role!=='instructor')return sgGatewayFailure('UNAUTHORIZED');if(command?.kind==='resolve_attention'){const expected=SG_PRODUCT_FIXTURE.professorAttentionRevision;if(command.expected_revision_id!==expected)return sgGatewayFailure('STALE_REVISION',`expected ${command?.expected_revision_id||'none'}; current ${expected}`);const idx=SG_PRODUCT_FIXTURE.professorAttention.findIndex(x=>x.id===command.attention_id);if(idx<0)return sgGatewayFailure('INVALID_COMMAND','unknown attention item');const item=SG_PRODUCT_FIXTURE.professorAttention[idx];if(item.action!=='resolve_local')return sgGatewayFailure('INVALID_COMMAND','this item requires class review');if(item.status==='resolved')return sgGatewaySuccess({...item});const next=Object.freeze({...item,status:'resolved',resolved_at:SG_QB15_FIXTURE_NOW});SG_PRODUCT_FIXTURE.professorAttention=[...SG_PRODUCT_FIXTURE.professorAttention.slice(0,idx),next,...SG_PRODUCT_FIXTURE.professorAttention.slice(idx+1)];SG_PRODUCT_FIXTURE.professorAttentionSeq+=1;SG_PRODUCT_FIXTURE.professorAttentionRevision=`prof-attention-r${SG_PRODUCT_FIXTURE.professorAttentionSeq}`;return sgGatewaySuccess({...next,attention_revision_id:SG_PRODUCT_FIXTURE.professorAttentionRevision})}
    if(command?.kind==='update_course_organisation'){const current=SG_PRODUCT_FIXTURE.professorOrganisation;if(command.expected_revision_id!==current.revision_id)return sgGatewayFailure('STALE_REVISION',`expected ${command?.expected_revision_id||'none'}; current ${current.revision_id}`);if(!sgQB15Course(command.course_id))return sgGatewayFailure('INVALID_COMMAND','unknown course');const old=current.courses[command.course_id]||{},patch={};if('pinned' in (command.patch||{}))patch.pinned=Boolean(command.patch.pinned);if('favourite' in (command.patch||{}))patch.favourite=Boolean(command.patch.favourite);if('colour' in (command.patch||{}))patch.colour=String(command.patch.colour||'forest');if('label' in (command.patch||{}))patch.label=String(command.patch.label||'').slice(0,32);if('sort' in (command.patch||{})){const allowed=['schedule','name','students','open_questions'];if(!allowed.includes(command.patch.sort))return sgGatewayFailure('INVALID_COMMAND','unsupported sort');patch.sort=command.patch.sort}const seq=current.revision_seq+1,courses={...current.courses,[command.course_id]:Object.freeze({...old,...patch})},sort=patch.sort||current.sort,next=Object.freeze({revision_id:`prof-org-r${seq}`,revision_seq:seq,sort,courses:Object.freeze(courses)});SG_PRODUCT_FIXTURE.professorOrganisation=next;return sgGatewaySuccess(sgQB15OrganisationCopy())}
    return sgGatewayFailure('INVALID_COMMAND',command?.kind||'missing')}

function sgR6OpenQuestions(){
  const rows=[];
  if(!sgR6.sharedAnswerApproved){rows.push(...SG_R6_QUESTIONS)}
  else if(!sgR6.exceptionResolved)rows.push(SG_R6_QUESTIONS[2]);
  for(const q of SG_R6_QUESTIONS){if(sgR6.studentFeedback[q.id]==='still_help'&&!rows.some(x=>x.id===q.id))rows.push(q)}
  return rows
}

function sgR6AttentionItems(){
  const rows=[];
  if(!sgR6.assessmentConfirmed)rows.push({id:'assessment',title:`Review ${sgR6.assessment.title}`,why:'StudyGrid found an assessment date and coverage in the example syllabus. Nothing is released to students until you review it.',reason:'Action needed: confirm or edit the detected details.',label:'Review quiz'});
  if(!sgR6.sharedAnswerApproved)rows.push({id:'questions',title:'Review 3 related questions',why:'Three students asked about the same threshold distinction. The grouping is a suggestion; you decide whether it belongs together.',reason:'Action needed: review the group and approve one shared answer.',label:'Review questions'});
  else if(!sgR6.exceptionResolved)rows.push({id:'questions',title:'Review 1 unresolved question',why:'The shared answer covers the threshold distinction, but the arrest question needs a separate instructor-supported explanation.',reason:'Action needed: resolve the unsupported exception.',label:'Review question'});
  for(const q of SG_R6_QUESTIONS){if(sgR6.studentFeedback[q.id]==='still_help')rows.push({id:'student-'+q.id,title:`${q.name} still needs help`,why:'The student explicitly said the approved answer did not resolve their question.',reason:'Action needed: review the original question and follow up. This is feedback, not a grade or risk score.',label:'Review follow-up'})}
  return rows
}

