].map(s=>{let open=0,needs=false,reason='No open question requiring an instructor reply.';if(s.id==='marcus'&&!sgR6.exceptionResolved){open=1;needs=true;reason='Needs reply: arrest question remains unsupported by the shared answer.'}else if(sgR6.studentFeedback[s.id]==='still_help'){open=1;needs=true;reason='Needs reply: student explicitly said the answer did not resolve the question.'}else if(!sgR6.sharedAnswerApproved){open=1;needs=true;reason='Open question: related-question group has not been answered yet.'}else if(sgR6.studentFeedback[s.id]==='answered'){reason='Student marked the approved answer as resolving the question.'}else{reason='Approved answer available; waiting for student feedback.'}return {...s,open,needs,reason,feedback:sgR6.studentFeedback[s.id]}})}

function tag(){
   for(const entry of registry.entries){
     let nodes=[];try{nodes=document.querySelectorAll(entry.selector_hint)}catch(_e){continue}
     nodes.forEach(el=>{if(!el.dataset.componentId){el.dataset.componentId=entry.component_id;el.dataset.componentRev=String(entry.component_rev)}el.dataset.sgComponent=entry.component_id;el.dataset.sgRev=String(entry.component_rev);if(/sensitive-input|user-content/i.test(entry.sensitivity_class||''))el.dataset.sgSensitive='true'});
   }
 }
